window.THREADS["174820"] = {"tid": "174820", "title": "处男想出击求助", "category": "性息", "typeid": "13", "author": "fakercokewater", "uid": "475352", "date": "2026-8-14 03:58:50", "views": 19248, "replies": 15, "pages_fetched": 1, "post_count": 16, "cover": "", "all_images": [], "pan": [], "pan_floor": [], "article": {"author": "fakercokewater", "uid": "475352", "avatar": "", "date": "2026-8-14 03:58:50", "html": "我思想比较老派，因为不想结婚生子，所以工作了就一直两点一线，下班了就玩游戏也挺自在。一直是母单，但是年纪大了做爱这件事慢慢的就没办法不在意了。特别是经常会晨勃，我不想起来这事是不可能的。自己也想过找对象，但对我来说挺难的，没有社交圈，也不敢在街上要人微信，加上我会坦白我不结婚。同事有性格不错的，但人家要结婚生子，我就不想害人。所以也是纠结了很久，想着还是去PC吧。也不能白活一辈子，三十多岁了。所以希望各位大佬畅所欲言，回答我一些疑问，我这人做事比较墨迹爱规划很多，所以问题有点多<br />\n<br />\n1. 个人喜欢亚洲脸，不喜欢欧美，第一次推荐去哪里？<br />\n2. 目前有看到推荐去越南，说是价格便宜直接跟你待一天？但说有体味？<br />\n3. 如果去国外，想让对方换装，是自己买了带过去？<br />\n4. 在越南如果她跟你待一天，吃饭的话方便叫外卖吗？总不能自己出去吃放她在酒店，带出去感觉也不好<br />\n5. 出击的话推荐几月去人少一点？大家一般会准备什么？药？方便携带的吃的？套要自己带吗？<br />\n6. 如果论坛有看到出击的详细攻略，可以推荐我看下，谢谢。<br />\n7. 怎么选那种做爱经验少的？我其实也想跟一个生涩的人试试，第一次能找到处就更好了", "images": []}, "comments": [{"floor": 2, "author": "winken", "uid": "49690", "avatar": "", "date": "", "html": "<i class=\"pstatus\"> 本帖最後由 winken 於 2026-8-14 04:09 編輯 </i><br />\n<br />\n第一次，贵就贵点，建议去澳门，，安全很多，，澳门好多有名的桑拿，，不会乱坑客，，论坛也有好几个发过过程帖子了，，找一下，学习一下，，，多花几千，，安全，舒服。。。。别学人什么越南东南亚，到时怎么死都不知道<br />\n<br />\n论坛这就有2条经验帖子：<br />\n<a href=\"index.html#tid=167332\">https://www.javbus.com/forum/for ... =%E6%BE%B3%E9%97%A8</a><br />\n<br />\n<a href=\"index.html#tid=160512\">https://www.javbus.com/forum/for ... =%E6%BE%B3%E9%97%A8</a>", "images": []}, {"floor": 3, "author": "DN123F", "uid": "621763", "avatar": "", "date": "", "html": "第一次去香港或者澳门把，之前有大佬在论坛发过攻略的", "images": []}, {"floor": 4, "author": "gardenia", "uid": "308812", "avatar": "", "date": "", "html": "没想到想这么细致，期待后续", "images": []}, {"floor": 5, "author": "红玫瑰", "uid": "92255", "avatar": "", "date": "", "html": "国外记得戴套，无套虽然爽，但是容易火葬场", "images": []}, {"floor": 6, "author": "7474774", "uid": "264318", "avatar": "", "date": "", "html": "单身跑这么远干啥，认识的人里面总有人有渠道的，附近推荐一下或者大学城这种地方多的很", "images": []}, {"floor": 7, "author": "excellentlicker", "uid": "460118", "avatar": "", "date": "", "html": "你打什么游戏？农药和吃鸡，我就知道很多打游戏都打成固定炮友的，他们经常见面，先打游戏，在吃饭，再打炮，再接着打游戏。可别说多充实！", "images": []}, {"floor": 8, "author": "魔人啾啾", "uid": "661801", "avatar": "", "date": "", "html": "这么夸张吗，出击居然要出国。乐意花钱职业非职业不都随便找么，鸡米定律", "images": []}, {"floor": 9, "author": "sire.gt", "uid": "529562", "avatar": "", "date": "", "html": "单身一个人的话，没必要跑那么远，周边朋友介绍介绍，先熟悉熟悉，会玩了再去港澳", "images": []}, {"floor": 10, "author": "飞翔的大鸡", "uid": "356874", "avatar": "", "date": "", "html": "第一次没必要去那么远的地方吧，出去套路很多的，新手很容易被套路的，如果只是想尝鲜没必要的", "images": []}, {"floor": 11, "author": "pornograph", "uid": "425503", "avatar": "", "date": "", "html": "第一次要留个好印象，不然以后会留下心理阴影", "images": []}, {"floor": 12, "author": "Liverbird", "uid": "379210", "avatar": "", "date": "", "html": "我也是三十多的处男，但我不敢出击。一没钱，二怕出事，三怕得病。", "images": []}, {"floor": 13, "author": "bzwujun", "uid": "517009", "avatar": "", "date": "", "html": "钱如果够我其实挺建议去澳门，因为都是很好的货，而且正规", "images": []}, {"floor": 14, "author": "fetishpantyhose", "uid": "338250", "avatar": "", "date": "", "html": "越南都是老手，看你是雏，肯定骗你，服务也缩水<br />\n澳门是一个不错的选择，去个平价的金龙足够玩一次了", "images": []}, {"floor": 15, "author": "mianzhaoguaijie", "uid": "60928", "avatar": "", "date": "共 4 頁", "html": "首先，你在什么地方。其次，你准备花多少钱。最后，为了这点逼事出国？你不是疯了？第一次，不要上98，搞个95其实蛮好的。", "images": []}, {"floor": 16, "author": "fakercokewater", "uid": "475352", "avatar": "", "date": "", "html": "看来大部分建议我身边多找找和去香港澳门。我也怕PC后悔，确实想了很久，感觉自己已经性压抑了，经常看女生都会忍不住往那方面想，无奈实在没办法从身边解决，找国内的主要是怕被抓，但确实还是喜欢国内的人。我身边朋友都是平凡人正常结婚生子，没有那方面的人，二来我现在真的没有社交圈，主动改变太难了，玩游戏我也不聊天。。。我是福建的，本身我物欲就很低，很少很少花钱，所以如果我想的话花多少钱不会特别在意，人总要满足自己，当然我应该不会精虫上脑乱花，如果有大佬能引路国内，我也想了解看看", "images": []}]};
window.THREADS["167332"] = {"tid": "167332", "title": "澳门之行", "category": "交流", "typeid": "7", "author": "Jason_Icon", "uid": "454406", "date": "2026-2-13 16:40:41", "views": 63294, "replies": 44, "pages_fetched": 3, "post_count": 45, "cover": "assets/images/167332/UrnKUZK.jpeg", "all_images": ["assets/images/167332/UrnKUZK.jpeg", "assets/images/167332/pCqpuvX.jpeg", "assets/images/167332/8XiyYfj.jpeg", "assets/images/167332/vRVcwXo.jpeg", "assets/images/167332/dwp3SWM.jpeg", "assets/images/167332/sFOuPOY.jpeg"], "pan": [], "pan_floor": [], "article": {"author": "Jason_Icon", "uid": "454406", "avatar": "", "date": "2026-2-13 16:40:41", "html": "<i class=\"pstatus\"> 本帖最後由 Jason_Icon 於 2026-2-16 10:02 編輯 </i><br />\n<br />\n<div align=\"left\">前言：我想去澳门也是看了论坛里的兄弟介绍的所以想要去体验一下！发这个帖的目的是记录一下其次是分享下经验方便后续的兄弟！！</div><br />\n<div align=\"left\">准备：</div><div align=\"left\">1：港澳通行证需要提前准备，到当地的出入境管理局办理就行了！说是需要5-7个工作日实际上不需要这么久，其次就是第一次办理港澳通行证的时候，工作人员会问你什么时候去，去几次！我当时是说去一次，旅游！然后工作人员就帮我办理未来一年的签注，一次！后续你想再去的话再去出入境补签注就行了。</div><div align=\"left\">2：手机卡，香港澳门是需要开通手机漫游的！一般联系人工服务可以免费开通！我是联通和电信卡！推荐电信的因为电信卡是25/天无限流量，联通是25/天 一天就5G这点很坑！我用的是电信的，我是两架手机一个电信卡一个联通卡，我电信卡开通了然后分热点！</div><div align=\"left\">3：手机充电！！澳门充电的口和我们的不一样这点要注意，其次建议背个包带2个1万毫安的充电宝，现在1万毫安的充电宝很轻的！</div><div align=\"left\">4：如果行李带个比较多的话建议在下车以后就近找个地方行李寄存，我寄存了单价是10/天，也不贵！去澳门背个包去就行，这样最轻松，不然在澳门全程背着包拿着行李箱真的不得劲！</div><div align=\"left\">5：换汇！我建议换个500的澳门币+带个储蓄卡或者信用卡就行了，500澳门币平时买点小吃的啥的，因为澳门有些小店是不支持手机的，其次用手机微信支付宝支付很不划算的！因为是1：1，小金额你就用现金，大金额你就直接刷卡，刷卡的话是实时汇率的！你如果用微信或者支付宝支付很亏！</div><br />\n<img src=\"assets/images/167332/UrnKUZK.jpeg\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n<br />\n<br />\n<div align=\"left\">如图，如果我用微信支付宝支付的话我要付4399RMB，但是我刷的卡我实际付了</div><br />\n<img src=\"assets/images/167332/pCqpuvX.jpeg\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n<br />\n<br />\n<div align=\"left\">这里就省了600，我当时叫的中介反了800RMB实际上我就付了3000RMB！而且也不怕被查账！问起就说吃帝王蟹了不知道价格被坑了！当然了你要是有钱那当我没说！其次就是我也推荐叫中介安排很方便，我从拱北口岸进的出关以后直接安排车接我到水疗，第二天去又来接我，完事了还安排车送我到拱北口岸出关口，全程没有打过车！好评！</div><br />\n<div align=\"left\">出行：我是坐动车到珠海站下车从拱北口岸过关到澳门的！</div><br />\n<img src=\"assets/images/167332/8XiyYfj.jpeg\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n<br />\n<br />\n<img src=\"assets/images/167332/vRVcwXo.jpeg\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n<br />\n<br />\n<div align=\"left\">从这里进去，过关全程很方便，刷港澳通行证就行了！自动过关以后会有个纸质的凭证别丢，在澳门期间有可能会被查需要提供这个的。</div><br />\n<div align=\"left\">正题：我通关到了澳门以后，我是直接联系中介到拱北口岸接我，直接送我去水疗！我先去的“帝湖”找的中介有优惠1000澳门币或者返我800RMB，因为抖音上说骗子很多第一次接触，有防备心！所以中介是在我上车以后直接转了我800RMB！这点好评！</div><br />\n<img src=\"assets/images/167332/dwp3SWM.jpeg\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n<br />\n<br />\n<div align=\"left\">这是帝湖的价目表！</div><div align=\"left\">1699-2199是纯绿，以上就是一条龙了！进场以后给你一个手牌，先泡一会洗个澡然后会有越南妹帮你擦身你也可以洗澡的时候点个越南妹帮你搓背 得加钱！我点的3999有10%的服务费，但是有送两个项目，建议选择拔龙筋+其它，拔龙筋就是摸你大腿根会帮你撸，各种挑逗你受不了你也可以叫她带你进房帮你打要另外加钱就是！当然了如果你一开始打算好想要点双飞，然后你刚好年轻气盛你可以在大厅就让越南妹先帮你打一次，然后你在上楼包你物超所值！！帝湖是每个60分钟还是30分钟一次选秀 这个我记不清了，所有人一起在舞台上各种菜系主持人挨个介绍“欧美牛排、日本寿司、韩国泡菜、越南菜、中国八大菜系由你选择但是没有看到”非洲巧克力“不知道有没有，我不好那口也没问！”你可以1V1，也可以1V2，更可以几个朋友一个房间，然后中间换人PK，得加钱只需要一点点！</div><div align=\"left\">选好人以后你就可以去大厅休息一会然后上二楼！</div><br />\n<div align=\"left\">上楼以后告诉服务员你的手牌号，她会带你去房间然后你在房间等着就行了！我以为自己点的是个越南妹子结果进房间以后才发现是个重庆妹子！02年的！大概的流程就是：先帮你洗澡，然后水床20分钟，期间先蚂蚁上树弄得人痒痒的，接着胸推，然后舌尖漫游，足推，口，舔后花园，然后帮你洗干净擦干身子去床上，在床上会帮你口，胸推，你要是喜欢胸推就选胸大的，重庆妹子有拿冰块说是做高山流水用的，我让她口的时候用冰块，她怕我受不了我说没事！刚开始的时候那感觉“一激灵”我到现在忘不了特别是她口的时候猛吸，吸得我受不了！然后就是戴套自己坐上来各种动！期间说累了让我来疼她！说话娇滴滴的真让人受不了！这个得自己体验！言语真的没法描述太多。</div><br />\n<div align=\"left\">做完项目以后我在浴场直接找个位置休息过夜了！第二天10点出门的！出来以后可以去官也街逛逛直接步行过去就可以了很近！然后去了威尼斯人，在赌场被骗了5000就溜了！去了永丽皇宫看了音乐喷泉！随便逛逛走了一天特别累就需要休息了！本来我是打算去壹号的点个双的，但是中介推荐我去尊贵，尊贵买一送一价格实惠，说现在很多人都去尊贵，建议我可以去我没把持住就去了。</div><br />\n<div align=\"left\">尊贵我选的是两个越南妹，两个人可以出两次！但是时间还是60分钟就是说你得在一个小时出两次，实际上扣除20分钟水床以后杂七杂八的时间你得在半小时射2次我是顶不住！我直接说出一次就行了让她们给我服务好一点！其实可以先让越南妹在水床的时候先帮你口出来一次，然后再射一次这样最划算！我也是事后才意识到很后悔！！</div><br />\n<img src=\"assets/images/167332/sFOuPOY.jpeg\" loading=\"lazy\" class=\"gimg\" alt=\"\" onerror=\"this.style.display='none'\"><br />\n<br />\n<br />\n<div align=\"left\">尊贵和帝湖收费不同的是它没有税费啊，但是有个238的水床费前面不说后面结账才看到有，很坑这个帝湖是没有的！服务流程大差不差！不过越南妹子服务也挺好的！尊贵消费扣除优惠1000实际支出4075澳门币我刷卡实际付了3500RMB，而且不管是帝湖还是尊贵越南妹子的中文都是没得说比我之前在越南体验的时候要好太多了！当时还要用手机翻译！</div><br />\n<div align=\"left\">说个题外的：兄弟们嫌贵的可以去越南，越南就是繁琐一些，需要办护照弄签证的麻烦一些，其次就是越南语言不通第一次去的可能体验没有那么好！越南海防涂山花街那边快餐才100RMB还包房费啥的！那个更便宜！嫌澳门贵的可以去那边！我当时在越南体验的是95总共算下来才400RMB这样！论性价比确实是越南便宜！但是澳门安全啊！！而且体验会更好一些！感兴趣的兄弟可以留言我晚些时候可以另开一贴写一下我在越南的见闻！！供兄弟们参考！！</div><br />\n<br />\n<br />\n<div align=\"left\">接下来的目标就是想去日本体验一下论坛里兄弟介绍的日本泡泡浴了！！！等我真的去了再给大家发帖！</div><br />\n<br />\n<br />\n<div align=\"left\"><font size=\"5\"><font color=\"#ff0000\"><strong>备注下：很多兄弟私信我要中介的联系方式，我不知道论坛留VX会不会违规，中介我也是在抖音找的，兄弟们也可以自己是找找看，很容易找到的！如果真的想要我这个中介的兄弟自己私信我神秘代码，我会加你！我每个人都回复私聊的话，我没有那么多金币我吃不消的！</strong></font></font></div>", "images": ["assets/images/167332/UrnKUZK.jpeg", "assets/images/167332/pCqpuvX.jpeg", "assets/images/167332/8XiyYfj.jpeg", "assets/images/167332/vRVcwXo.jpeg", "assets/images/167332/dwp3SWM.jpeg", "assets/images/167332/sFOuPOY.jpeg"]}, "comments": [{"floor": 2, "author": "lxy6565", "uid": "385144", "avatar": "", "date": "", "html": "全下来3000块钱啊，安全啊！", "images": []}, {"floor": 3, "author": "gg11", "uid": "309418", "avatar": "", "date": "", "html": "介绍的很详细.一来一回几万没了.在国内也差不多.楼主现在这个环境还去日本。没问题嘛.", "images": []}, {"floor": 4, "author": "free5039", "uid": "19680", "avatar": "", "date": "", "html": "老哥身体力行 佩服 佩服", "images": []}, {"floor": 5, "author": "爱回家", "uid": "391098", "avatar": "", "date": "", "html": "过程写得很详细了，很有指导作用。<br />\n要是有妹子的照片就更好了。<br />\n总体看，香港适合低价快餐，澳门适合高价服务，各有所长。", "images": []}, {"floor": 6, "author": "shen88", "uid": "80726", "avatar": "", "date": "", "html": "大佬，请教下，为什么帝湖双比单还要便宜？", "images": []}, {"floor": 7, "author": "Jason_Icon", "uid": "454406", "avatar": "", "date": "", "html": "<div class=\"quote\"><blockquote><font size=\"2\"><a href=\"https://www.javbus.com/forum/forum.php?mod=redirect&amp;goto=findpost&amp;pid=4615153&amp;ptid=167332\" target=\"_blank\"><font color=\"#999999\">shen88 發表於 2026-2-13 17:10</font></a></font><br />\n大佬，请教下，为什么帝湖双比单还要便宜？</blockquote></div><br />\n那是加钱，双的话要在单的前提下再加这么多！", "images": []}, {"floor": 8, "author": "sosresult", "uid": "489778", "avatar": "", "date": "", "html": "啊，我想去澳门看高达，闪光的哈萨维2，不过专门去一趟看电影成本挺高的。", "images": []}, {"floor": 9, "author": "Jason_Icon", "uid": "454406", "avatar": "", "date": "", "html": "<div class=\"quote\"><blockquote><font size=\"2\"><a href=\"https://www.javbus.com/forum/forum.php?mod=redirect&amp;goto=findpost&amp;pid=4615147&amp;ptid=167332\" target=\"_blank\"><font color=\"#999999\">爱回家 發表於 2026-2-13 17:04</font></a></font><br />\n过程写得很详细了，很有指导作用。<br />\n要是有妹子的照片就更好了。<br />\n总体看，香港适合低价快餐，澳门适合高价服 ...</blockquote></div><br />\n<font color=\"#333333\"><font face=\"&amp;quot\"><font style=\"font-size:16px\">在澳门，‌</font></font></font><font style=\"color:rgb(51, 51, 51)\"><font face=\"&amp;quot\"><font style=\"font-size:16px\">没有经过他人同意，是不可以拍照的</font></font></font><font color=\"#333333\"><font face=\"&amp;quot\"><font style=\"font-size:16px\">‌，特别是这种地方 你觉得妹子会同意你拍照么？别瞎搞 到时候在牢里过年就尬了！</font></font></font>", "images": []}, {"floor": 10, "author": "秋名山委员", "uid": "305720", "avatar": "", "date": "", "html": "感谢老哥涨知识，收藏了，万一需要过去澳门体验，此攻略可是指南", "images": []}, {"floor": 11, "author": "顺子不二", "uid": "588917", "avatar": "", "date": "", "html": "卧槽，牛逼，很详细，给哥们玩爽了，哈哈哈哈", "images": []}, {"floor": 12, "author": "qw2825058", "uid": "413476", "avatar": "", "date": "", "html": "真好啊，真想去体验一下，就是这价格对于我来说有点贵了，没办法打工人干一个月就为了这一个小时还是肉疼，我考票才三千多哈哈哈", "images": []}, {"floor": 13, "author": "FootballManager", "uid": "614463", "avatar": "", "date": "", "html": "想问一下，价目表上面的服务都是1个小时的价格吗？", "images": []}, {"floor": 14, "author": "chenshimei", "uid": "140625", "avatar": "", "date": "", "html": "看了一下自己月入就3k，感觉还是自己撸划算，不过也感谢分享，涨姿势了。", "images": []}, {"floor": 15, "author": "smz0000", "uid": "527966", "avatar": "", "date": "共 7 頁", "html": "想问问大佬越南lincherry或者龙宫的颜值怎么样啊，澳门的颜值很漂亮吗", "images": []}, {"floor": 16, "author": "打胶牛", "uid": "557138", "avatar": "", "date": "", "html": "澳门体验一两次还是香港扫楼更具性价比", "images": []}, {"floor": 17, "author": "绅士三分钟", "uid": "483009", "avatar": "", "date": "", "html": "你用微信或者支付宝选择银行卡付款也是一比一吗", "images": []}, {"floor": 18, "author": "ggflame", "uid": "307269", "avatar": "", "date": "", "html": "仰望高端操作", "images": []}, {"floor": 19, "author": "DriverGirl", "uid": "122813", "avatar": "", "date": "", "html": "涨知识了", "images": []}, {"floor": 20, "author": "雷锋老湿", "uid": "663666", "avatar": "", "date": "", "html": "穷人只能看看了，之前去澳门旅游都没玩这种", "images": []}, {"floor": 21, "author": "Emon", "uid": "96412", "avatar": "", "date": "", "html": "澳门转的也多", "images": []}, {"floor": 22, "author": "dyc1271663340", "uid": "503177", "avatar": "", "date": "", "html": "之前老刷到胡志明那个播主&nbsp;&nbsp;天天去足疗店1-200可以刮胡子再到按摩&nbsp;&nbsp;不知道后面有没有大保健 好好奇啊", "images": []}, {"floor": 23, "author": "依山傍水", "uid": "593064", "avatar": "", "date": "", "html": "攻略很全面，等我有钱有闲了试试", "images": []}, {"floor": 24, "author": "德意志", "uid": "46801", "avatar": "", "date": "", "html": "期待你的越南行攻略。澳门太贵了，还是越南划算点，来回机票才多少钱。", "images": []}, {"floor": 25, "author": "luanlinye", "uid": "449716", "avatar": "", "date": "", "html": "羡慕楼主有钱又有精力啊，短时间连射两次我都不行", "images": []}, {"floor": 26, "author": "vikp", "uid": "487937", "avatar": "", "date": "", "html": "日本暂时别去了，X上油管上全是让中国人滚出日本的，本来去飞田新地这些有时候遇到樱花妹就很丧，以后估计遇到你中国人服务更敷衍，甚至故意搞你", "images": []}, {"floor": 27, "author": "yurenleonid", "uid": "428852", "avatar": "", "date": "", "html": "请教下中介是电报上找的？有什么途径可以联系到呢。。", "images": []}, {"floor": 28, "author": "地球操人", "uid": "632695", "avatar": "", "date": "", "html": "期待东瀛浪人行", "images": []}, {"floor": 29, "author": "aids19831019", "uid": "633918", "avatar": "", "date": "", "html": "就服务来讲还不错 算上往返路费和时间的话大差不大", "images": []}, {"floor": 30, "author": "qwert8520", "uid": "379378", "avatar": "", "date": "共 7 頁", "html": "和我的体验和帖子介绍都差不多，我发的时候一群拿着不知道多少年前经验的人来指手画脚真是醉了。", "images": []}, {"floor": 31, "author": "的萨芬斯", "uid": "319640", "avatar": "", "date": "", "html": "没找过啊，请教一下有经验的老哥，如果是射的快那岂不是很亏了？&nbsp;&nbsp;还是她们是按时间来算的啊", "images": []}, {"floor": 32, "author": "laco", "uid": "562437", "avatar": "", "date": "", "html": "大神呢篇出击攻略写得真系好。", "images": []}, {"floor": 33, "author": "册册册册", "uid": "48496", "avatar": "", "date": "", "html": "<div class=\"quote\"><blockquote><font size=\"2\"><a href=\"https://www.javbus.com/forum/forum.php?mod=redirect&amp;goto=findpost&amp;pid=4615301&amp;ptid=167332\" target=\"_blank\"><font color=\"#999999\">smz0000 發表於 2026-2-13 19:47</font></a></font><br />\n想问问大佬越南lincherry或者龙宫的颜值怎么样啊，澳门的颜值很漂亮吗</blockquote></div><br />\n越南强就强在服装统一加白 你晚上逛日本街一家一套服装 给力", "images": []}, {"floor": 34, "author": "斯巴达克斯", "uid": "463766", "avatar": "", "date": "", "html": "<div class=\"quote\"><blockquote><font size=\"2\"><a href=\"https://www.javbus.com/forum/forum.php?mod=redirect&amp;goto=findpost&amp;pid=4615138&amp;ptid=167332\" target=\"_blank\"><font color=\"#999999\">gg11 發表於 2026-2-13 16:52</font></a></font><br />\n介绍的很详细.一来一回几万没了.在国内也差不多.楼主现在这个环境还去日本。没问题嘛. ...</blockquote></div><br />\n楼主说的问题是现在日本那边梅D激增", "images": []}, {"floor": 35, "author": "东京梦华录", "uid": "311894", "avatar": "", "date": "", "html": "看起来比内地一些便宜", "images": []}, {"floor": 36, "author": "不良人", "uid": "291355", "avatar": "", "date": "", "html": "其实我更建议在隔壁zh，tg上自聊的就五六百", "images": []}, {"floor": 37, "author": "230it", "uid": "673728", "avatar": "", "date": "", "html": "收藏了，指导意义绝佳，准备年后开工前试一下哈哈哈哈", "images": []}, {"floor": 38, "author": "xiexiedajia", "uid": "336459", "avatar": "", "date": "", "html": "大佬，中介这个什么的怎么收费的", "images": []}, {"floor": 39, "author": "乌鸡白凤丸", "uid": "689660", "avatar": "", "date": "", "html": "流程看着不复杂，想做伸手党要鸡头vx<img src=\"static/image/smiley/javbus/1.png\" smilieid=\"86\" border=\"0\" onerror=\"this.style.display='none'\" alt=\"\" />", "images": []}, {"floor": 40, "author": "zzll333", "uid": "633716", "avatar": "", "date": "", "html": "希望来一份越南攻略，我想年中去越南体验一下", "images": []}, {"floor": 41, "author": "qq192123", "uid": "469443", "avatar": "", "date": "", "html": "澳门玩竟然这么贵", "images": []}, {"floor": 42, "author": "牛牛要爆了", "uid": "595569", "avatar": "", "date": "", "html": "好贵，普通人想去一次还是十分肉疼，只能看老哥描述幻想一下了<img src=\"static/image/smiley/javbus/39.png\" smilieid=\"118\" border=\"0\" onerror=\"this.style.display='none'\" alt=\"\" />", "images": []}, {"floor": 43, "author": "SMF", "uid": "129885", "avatar": "", "date": "", "html": "所以说啊，有钱真好。", "images": []}, {"floor": 44, "author": "s2062413731", "uid": "691801", "avatar": "", "date": "", "html": "太有魅力了", "images": []}, {"floor": 45, "author": "lblk", "uid": "646071", "avatar": "", "date": "共 7 頁", "html": "澳门一直想去，但是感觉价格也不便宜啊···", "images": []}]};
